      "lines": 74,
      "category": "Arquitectura",
      "decision": "Optional",
      "owner": "design-code-structure (modelado condicional)",
      "summary": "Aclara términos del dominio, mantiene un glosario y registra decisiones relevantes como ADR.",
      "reason": "Aporta escenarios concretos para aclarar términos e invariantes antes de fijar el diseño; el glosario y los ADR siguen el alcance documental del proyecto.",
      "caution": "No crear GLOSSARY.md ni ADR para cambios corrientes ni sustituir las convenciones documentales existentes."
