        "summary": "Apply when designing types, reviewing a function signature, or writing code in any statically-typed language. Make illegal states unrepresentable, brand semantic primitives, parse external data at boundaries, refuse to lie to the compiler, exhaust variants, derive from authoritative schemas.",
        "reason": "Use the simplest type that makes a required operation total; model related states, meaningful identities and exhaustive variants. Validate at the owning boundary and derive types from the authoritative contract. Require evidence for claimed guarantees and keep instructions focused on decisions not mechanical style.",
