        "decision": "Adapt contract and runtime distinctions",
        "reason": "The guide explicitly distinguishes generated types from validation and readonly/as const from runtime immutability. Retain these cautions and avoid changing optionality or public interfaces merely to satisfy a style preference.",
        "reviewDepth": "All nine complete skill entrypoints: discriminated-unions, functions, naming, react, source-organization, style-guide, tests, types, and variables. Duplicate reference text not counted as a separate full review.",
